[metadata] {"type": "create", "filePath": "/app/src/main/java/com/example/customers/domain/NameSearch.java", "content": "package com.example.customers.domain;

import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * How the backend compares typed text with a customer name.
 *
 * <p>Names are matched case- and accent-insensitively in both directions:
 * {@code makinen} and {@code MAKINEN} match {@code Mäkinen}, and {@code mäkinen}
 * matches {@code Makinen}. That is done by folding both sides down to the same
 * normal form — lower case, diacritics removed — before comparing.
 */
public final class NameSearch {

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");

    private NameSearch() {
    }

    /**
     * Folds text down to the form used for comparison: decomposed, stripped of
     * combining marks and lower-cased.
     */
    public static String normalize(String text) {
        if (text == null || text.isEmpty()) {
            return "";
        }
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }

    /**
     * Splits text into terms on whitespace. Leading, trailing and repeated
     * whitespace is not significant, so blank text yields no terms at all.
     */
    public static List<String> split(String text) {
        if (text == null || text.isBlank()) {
            return List.of();
        }
        return List.of(WHITESPACE.split(text.strip()));
    }

    /** {@link #split(String)}, with every term {@link #normalize(String) normalized}. */
    public static List<String> terms(String text) {
        return split(text).stream().map(NameSearch::normalize).toList();
    }
}
