    public List<CustomerStatus> orderedStatuses() {
        return statuses.stream()
                .sorted(Comparator.comparingInt(CustomerStatus::ordinal))
                .toList();
    }

    /** {@code true} when this filter keeps every customer. */
    public boolean isEmpty() {
        return nameTerms().isEmpty() && statuses.isEmpty();
    }

    @Override
    public String toString() {
        return "CustomerFilter[name=" + canonicalName() + ", statuses="
                + orderedStatuses().stream().map(CustomerStatus::name).collect(Collectors.joining(",")) + "]";
