+        assertEquals("", query());
+    }
+
+    // -- what typing costs --------------------------------------------------
+
+    @Test
+    void aBurstOfTypingIsOneQuery() {
+        settle();
+        queryLog.clear();
+
+        nameInput().pressSequentially("aaltonen");
+        settle();
+
+        assertEquals("Showing 15 of 500", summary());
+        assertTrue(queryLog.countQueries().size() <= 2,
