+        return page.locator("#filter-summary").innerText().trim();
+    }
+
+    private String query() {
+        String rawQuery = URI.create(page.url()).getRawQuery();
+        return rawQuery == null || rawQuery.isEmpty() ? "" : "?" + rawQuery;
+    }
+
+    private int historyLength() {
+        return ((Number) page.evaluate("() => window.history.length")).intValue();
+    }
+}
